// Infernal Offers as the game defines them: names and boon/bane text come from the Diablo IV
// client strings (data/game-text.json, regenerated by scripts/import-game-text.mjs).
// Text © Blizzard Entertainment; quoted for reference with attribution.
import gameText from './data/game-text.json';

export const GAME_TEXT_SOURCE=gameText.source;

/** The game's offer categories (the icon on each offer). The Black Pact matches on these. */
export type OfferFamily='Masses'|'Spires'|'Hellborne'|'Fiends'|'Lords'|'Monsters'|'Hellfire'|'Player boon'|'Player bane'|'Council'|'Special boss'|'Chaos';
const FAMILY_BY_ICON:Readonly<Record<string,OfferFamily>>={
 BSK_AetherMass:'Masses',BSK_Soulspire:'Spires',BSK_Hellborne:'Hellborne',BSK_AetherHost:'Fiends',BSK_GreaterHost:'Lords',
 BSK_Mob:'Monsters',BSK_Hellfire:'Hellfire',BSK_PlayerBoon:'Player boon',BSK_PlayerBane:'Player bane',BSK_Council:'Council',
 BSK_SpecialBoss:'Special boss',Icon_Tooltip_Chaos:'Chaos'
};

/**
 * A bane that threatens the player rather than costing time. HordeMind flags danger and
 * never prices it: dying carries no penalty (owner, S15), and time-costing banes are
 * already simulated.
 */
export interface Danger{level:'high'|'some';why:string}
export interface OfferRef{
 /** Stable id recorded in runs: the game's name, disambiguated when two offers share it. */
 id:string;label:string;family:OfferFamily;boon:string;bane:string;hint:string;
 /** Internal game key, e.g. "GestatingMasses" for The Teeming Masses. */
 gameKey:string;
 /** Card colour tier in the game's text. */
 tier:string|null;
 danger?:Danger;
}

// Two offers share the name "The Summoned Hellborne"; their banes tell them apart.
const DISAMBIGUATE:Readonly<Record<string,string>>={SkulkingHellborne:'hunting you',SummonedHellborne:'spawn with events'};

export const OFFERS:OfferRef[]=gameText.offers.map(o=>{
 const id=DISAMBIGUATE[o.key]?`${o.name} (${DISAMBIGUATE[o.key]})`:o.name;
 const hint=o.bane?`${o.boon}. Bane: ${o.bane}.`:`${o.boon}.`;
 return {id,label:id,family:FAMILY_BY_ICON[o.category??'']??'Monsters',boon:o.boon,bane:o.bane,hint,gameKey:o.key,tier:o.tier};
}).sort((a,b)=>a.label.localeCompare(b.label));

// HordeMind's reading of each bane, from the game's bane text; not a measurement.
// High: hazards aimed at you. Some: more incoming damage or weaker defences.
export const DANGER:Readonly<Record<string,Danger>>={
 'The Burning Rain':{level:'high',why:'Hellfire rains upon you'},
 'The Wrath of Hell':{level:'high',why:'Hellfire intensifies'},
 'The Stalking Devil':{level:'high',why:'A demon of great power has your scent'},
 'The Ambushing Hellborne':{level:'high',why:'Hellborne can now ambush you'},
 'The Summoned Hellborne (hunting you)':{level:'high',why:'Hellborne are hunting you'},
 'The Draining Spires':{level:'high',why:'Soulspires drain health'},
 'The Colossal Fiends':{level:'high',why:'Aether Lords cause Hellfire to erupt around them'},
 'The Puffing Masses':{level:'some',why:'Damage from Masses applies Vulnerable'},
 'The Bursting Masses':{level:'some',why:'Masses deal unavoidable damage'},
 'The Hellish Masses':{level:'some',why:'Masses explode on death'},
 'The Anchored Masses':{level:'some',why:'Masses have greatly increased attack speed'},
 'The Ruthless Lords':{level:'some',why:'Aether Lords gain health and damage for each spawn'},
 'The Fiendish Legions':{level:'some',why:'Elite and Aether Fiend damage increased'},
 'The Exalted Hellborne':{level:'some',why:'Hellborne damage is increased'},
 'The Meteoric Hellborne':{level:'some',why:'Hellborne damage increased'},
 'The Invigorating Hellborne':{level:'some',why:'Hellborne damage +25%'},
 'The Rising Spires':{level:'some',why:'Soulspires empower enemies'},
 'The Exalted Hordes':{level:'some',why:'Normal monster damage increased'},
 'The Aether Rush':{level:'some',why:'Normal monster damage +25%'},
 'The Unstoppable Elite':{level:'some',why:'Elites are Unstoppable'},
 'The Exalted Council':{level:'some',why:'The Fell Council damage +50%'},
 'The Wanderer Withered':{level:'some',why:'All Resist −10%'},
 'The Wanderer Exhausted':{level:'some',why:'Evade cooldown +2 seconds'},
 'The Wanderer Enfeebled':{level:'some',why:'Potion cooldown +2 seconds'}
};
for(const o of OFFERS){const d=DANGER[o.label];if(d)o.danger=d}

/** Infernal Hordes compass wave caps (Warcraft Tavern, Season 15). */
export const COMPASSES=[[10,'Legendary compass'],[8,'Rare compass'],[6,'Magic compass'],[4,'Fleeting compass']] as const;

/** Names earlier HordeMind versions recorded, so saved runs still resolve. */
export const OFFER_ALIASES:Readonly<Record<string,string>>={
 'Chaotic Offering':'The Chaotic Offering',
 'The Gorging Masses':'The Gorging Mass',
 'The Enfeebled Wanderer':'The Wanderer Enfeebled',
 'The Exhausted Wanderer':'The Wanderer Exhausted',
 'The Withered Wanderer':'The Wanderer Withered'
};

const fold=(s:string)=>s.toLowerCase().replace(/^the\s+/,'').trim();
const byLabel=new Map(OFFERS.map(o=>[o.label.toLowerCase(),o]));

/** Exact catalog entry for typed text, ignoring case and a leading "The"; accepts earlier names. */
export function resolveOffer(text:string):OfferRef|null{
 const trimmed=text.trim(),key=(OFFER_ALIASES[trimmed]??trimmed).toLowerCase();
 return byLabel.get(key)??OFFERS.find(o=>fold(o.label)===fold(key))??null;
}

/** Browsing order for the picker: the categories players think in, Chaos last. */
export const FAMILY_ORDER:readonly OfferFamily[]=['Masses','Spires','Hellborne','Fiends','Lords','Monsters','Hellfire','Player boon','Player bane','Council','Special boss','Chaos'];
const byFamily=[...OFFERS].sort((a,b)=>FAMILY_ORDER.indexOf(a.family)-FAMILY_ORDER.indexOf(b.family)||a.label.localeCompare(b.label));

/**
 * Ranks offers for the picker. Every query word must match the name, category or
 * description; name matches outrank description matches. An empty query lists
 * recent offers first, then the whole catalog grouped by category.
 */
export function searchOffers(query:string,recent:readonly string[]=[]):OfferRef[]{
 const words=query.toLowerCase().split(/\s+/).filter(w=>w&&w!=='the');
 if(!words.length){
  const recentRefs=recent.map(resolveOffer).filter((o):o is OfferRef=>o!==null);
  return [...new Set([...recentRefs,...byFamily])];
 }
 const scored=OFFERS.map(offer=>{
  const name=fold(offer.label),nameWords=name.split(/\s+/),family=offer.family.toLowerCase(),hint=offer.hint.toLowerCase();
  let score=0;
  for(const w of words){
   if(name.startsWith(w))score+=100;
   else if(nameWords.some(x=>x.startsWith(w)))score+=80;
   else if(name.includes(w))score+=60;
   else if(family.includes(w))score+=40;
   else if(hint.includes(w))score+=20;
   else return {offer,score:0};
  }
  return {offer,score:score+(recent.includes(offer.label)?5:0)};
 });
 return scored.filter(x=>x.score>0).sort((a,b)=>b.score-a.score||a.offer.label.localeCompare(b.offer.label)).map(x=>x.offer);
}
